let quote: string | null = null;
for (let i = 0; i < rest.length; i++) {
  const ch = rest[i];
  if (quote) {
    if (ch === quote) quote = null;
    continue;
  }
  if (ch === "'" || ch === '"') quote = ch;
  else if (ch === '#' && (i === 0 || /\s/.test(rest[i - 1]))) return rest.slice(0, i);
}
return rest;

